The property of morphisms of germs of schemes
\begin{align*}
& \mathcal{P}((X, x) \to (S, s)) = \\
& \text{the local ring }
\mathcal{O}_{X_s, x}
\text{ of the fibre is Noetherian and Gorenstein}
\end{align*}
is \'etale local on the source-and-target (Descent, Definition
\ref{descent-definition-local-source-target-at-point}).

There exist an open substack
$\Curvesstack^{Gorenstein, 1} \subset \Curvesstack$ such that
\begin{enumerate}
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{Gorenstein, 1}$,
\item the morphism $X \to S$ is Gorenstein and has
relative dimension $1$ (Morphisms of Spaces, Definition
\ref{spaces-morphisms-definition-relative-dimension}),
\end{enumerate}
\item given a scheme $X$ proper over a field $k$ with $\dim(X) \leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{Gorenstein, 1}$,
\item $X$ is Gorenstein and $X$ is equidimensional of
dimension $1$.
\end{enumerate}
\end{enumerate}

In Algebraic and Formal Geometry, Situation
\ref{algebraization-situation-bootstrap}
we have $H^s_\mathfrak a(M) = \lim H^s_\mathfrak a(M/I^nM)$.

Properties (A), (B), (C), (D), and (E) of
More on Algebra, Section \ref{more-algebra-section-properties-formal-fibres}
hold for $P(k \to R) =$``$R$ is a Gorenstein ring''.

Assume that $\mathcal{C}$ is a site,
and $U$ is an object of $\mathcal{C}$ whose associated representable
presheaf is a sheaf. Constructions A and B above define
mutually inverse (!) functors of $2$-categories
$$
\left\{
\begin{matrix}
2\text{-category of}\\
\text{stacks over }\mathcal{C}/U
\end{matrix}
\right\}
\leftrightarrow
\left\{
\begin{matrix}
2\text{-category of pairs }(\mathcal{T}, p)
\text{ consisting} \\
\text{of a stack }\mathcal{T}\text{ over }\mathcal{C}\text{ and a morphism} \\
p : \mathcal{T} \to \mathcal{C}/U\text{ of stacks over }\mathcal{C}
\end{matrix}
\right\}
$$

The ``boundary'' map
$\delta : \Omega^\bullet_{X/S} \to \Omega^\bullet_{X/S}[2]$
in $D(X, f^{-1}\mathcal{O}_S)$ coming from
the short exact sequence in Lemma \ref{lemma-the-complex-for-L-star}
is the map of Remark \ref{remark-cup-product-as-a-map}
for $\xi = c_1^{dR}(\mathcal{L})$.

There exist an open substack $\Curvesstack^{CM, 1} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{CM, 1}$,
\item the morphism $X \to S$ is Cohen-Macaulay and has
relative dimension $1$ (Morphisms of Spaces, Definition
\ref{spaces-morphisms-definition-relative-dimension}),
\end{enumerate}
\item given a scheme $X$ proper over a field $k$ with $\dim(X) \leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{CM, 1}$,
\item $X$ is Cohen-Macaulay and $X$ is equidimensional of
dimension $1$.
\end{enumerate}
\end{enumerate}

There exist an open substack $\Curvesstack^{grc, 1} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{grc, 1}$,
\item the geometric fibres of the morphism $X \to S$ are
reduced, connected, and have dimension $1$,
\end{enumerate}
\item given a scheme $X$ proper over a field $k$ with $\dim(X) \leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{grc, 1}$,
\item $X$ is geometrically reduced, geometrically connected,
and has dimension $1$.
\end{enumerate}
\end{enumerate}

Let $\mathcal{F}$ be a predeformation category.
Let $\xi$ be a versal formal object of $\mathcal{F}$ lying over
$R \in \Ob(\widehat{\mathcal{C}}_\Lambda)$. The following are
equivalent
\begin{enumerate}
\item $\mathcal{F}$ is unobstructed, and
\item $\Lambda \to R$ is formally smooth in the $\mathfrak m_R$-adic topology.
\end{enumerate}
In the classical case these are also equivalent to
\begin{enumerate}
\item[(3)] $R \cong \Lambda[[x_1, \ldots, x_n]]$ for some $n$.\
\end{enumerate}

There exist an open substack $\Curvesstack^{Gorenstein} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{Gorenstein}$,
\item the morphism $X \to S$ is Gorenstein,
\end{enumerate}
\item given a scheme $X$ proper over a field $k$ with $\dim(X) \leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{Gorenstein}$,
\item $X$ is Gorenstein.
\end{enumerate}
\end{enumerate}

Let $S$ be a scheme. Let $X$ be a decent algebraic space over $S$.
Let $x \in |X|$ be a closed point such that $U = X \setminus \{x\} \to X$
is quasi-compact. With
$V = \Spec(\mathcal{O}_{X, x}^h) \setminus \{\mathfrak m_x^h\}$
the base change functor
$$
\left\{
\begin{matrix}
f : Y \to X\text{ of finite presentation} \\
f^{-1}(U) \to U\text{ is an isomorphism}
\end{matrix}
\right\}
\longrightarrow
\left\{
\begin{matrix}
g : Y \to \Spec(\mathcal{O}_{X, x}^h)\text{ of finite presentation} \\
g^{-1}(V) \to V\text{ is an isomorphism}
\end{matrix}
\right\}
$$
is an equivalence of categories.

Schemes, Lemma \ref{schemes-lemma-push-forward-quasi-coherent}
is sharp in the sense that one can neither drop the assumption
of quasi-compactness nor the assumption of quasi-separatedness.

The functor
$$
\begin{matrix}
\text{crystals in quasi-coherent} \\
\mathcal{O}_{X/S}\text{-modules on }\text{Cris}(X/S)
\end{matrix}
\longrightarrow
\begin{matrix}
\text{pairs }(M, \nabla)\text{ satisfying} \\
\text{(\ref{item-complete}), (\ref{item-connection}),
(\ref{item-integrable}), and (\ref{item-topologically-quasi-nilpotent})}
\end{matrix}
$$
of Lemma \ref{lemma-crystals-on-affine}
is an equivalence of categories.

Given a commutative diagram
$$
\xymatrix{
X' \ar[r]_f \ar[d] & X \ar[d] \\
S' \ar[r] & S
}
$$
of schemes the diagrams
$$
\xymatrix{
\Pic(X') \ar[d]_{c_1^{dR}} &
\Pic(X) \ar[d]^{c_1^{dR}} \ar[l]^{f^*} \\
H^2_{dR}(X'/S') &
H^2_{dR}(X/S) \ar[l]_{f^*}
}
\quad
\xymatrix{
\Pic(X') \ar[d]_{c_1^{Hodge}} &
\Pic(X) \ar[d]^{c_1^{Hodge}} \ar[l]^{f^*} \\
H^1(X', \Omega^1_{X'/S'}) &
H^1(X, \Omega^1_{X/S}) \ar[l]_{f^*}
}
$$
commute.

The property of morphisms of germs of schemes
\begin{align*}
& \mathcal{P}((X, x) \to (S, s)) = \\
& \text{the local ring }
\mathcal{O}_{X_s, x}
\text{ of the fibre is Noetherian and Cohen-Macaulay}
\end{align*}
is \'etale local on the source-and-target (Descent, Definition
\ref{descent-definition-local-source-target-at-point}).

There is a decomposition into open and closed substacks
$$
\Curvesstack^{prestable} = \coprod\nolimits_{g \geq 0}
\Curvesstack^{prestable}_g
$$
where each $\Curvesstack^{prestable}_g$ is characterized as follows:
\begin{enumerate}
\item given a family of curves $f : X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{prestable}_g$,
\item $X \to S$ is a prestable family of curves and
$R^1f_*\mathcal{O}_X$ is a locally free $\mathcal{O}_S$-module of rank $g$,
\end{enumerate}
\item given $X$ a scheme proper over a field $k$ with
$\dim(X) \leq 1$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$
factors through $\Curvesstack^{prestable}_g$,
\item the singularities of $X$ are at-worst-nodal, $\dim(X) = 1$,
$k = H^0(X, \mathcal{O}_X)$, and the genus of $X$ is $g$.
\end{enumerate}
\end{enumerate}

Let $S$ be a scheme.
Let $Y \to X$ be a morphism of $(\textit{Spaces}/S)_\etale$.
\begin{enumerate}
\item If $\mathcal{I}$ is injective in
$\textit{Ab}((\textit{Spaces}/X)_\etale)$, then
\begin{enumerate}
\item $i_f^{-1}\mathcal{I}$ is injective in $\textit{Ab}(Y_\etale)$,
\item $\mathcal{I}|_{X_\etale}$ is injective in $\textit{Ab}(X_\etale)$,
\end{enumerate}
\item If $\mathcal{I}^\bullet$ is a K-injective complex
in $\textit{Ab}((\textit{Spaces}/X)_\etale)$, then
\begin{enumerate}
\item $i_f^{-1}\mathcal{I}^\bullet$ is a K-injective complex in
$\textit{Ab}(Y_\etale)$,
\item $\mathcal{I}^\bullet|_{X_\etale}$ is a K-injective complex in
$\textit{Ab}(X_\etale)$,
\end{enumerate}
\end{enumerate}
The corresponding statements for modules do not hold.

There exist an open substack $\Curvesstack^{prestable} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $f : X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{prestable}$,
\item $X \to S$ is a prestable family of curves,
\end{enumerate}
\item given $X$ a scheme proper over a field $k$ with
$\dim(X) \leq 1$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$
factors through $\Curvesstack^{prestable}$,
\item the singularities of $X$ are at-worst-nodal, $\dim(X) = 1$,
and $k = H^0(X, \mathcal{O}_X)$.
\end{enumerate}
\end{enumerate}

Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$.
The following are equivalent:
\begin{enumerate}
\item $f$ is finite locally free,
\item $f$ is finite, flat, and locally of finite presentation.
\end{enumerate}
If $Y$ is locally Noetherian these are also equivalent to
\begin{enumerate}
\item[(3)] $f$ is finite and flat.
\end{enumerate}

There exist an open substack $\Curvesstack^{h0, 1} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $f : X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{h0, 1}$,
\item $f_*\mathcal{O}_X = \mathcal{O}_S$, this holds
after arbitrary base change, and the fibres of $f$ have dimension $1$,
\end{enumerate}
\item given a scheme $X$ proper over a field $k$ with $\dim(X) \leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{h0, 1}$,
\item $H^0(X, \mathcal{O}_X) = k$ and $\dim(X) = 1$.
\end{enumerate}
\end{enumerate}

\begin{reference}
\cite[Theorem 2.2.5]{Conrad-moduli}
\end{reference}
Let $\mathcal{X} \subset \mathcal{X}'$ be a thickening of algebraic
stacks. Then
\begin{enumerate}
\item $\mathcal{X}$ is an algebraic space if and only if $\mathcal{X}'$
is an algebraic space,
\item $\mathcal{X}$ is a scheme if and only if $\mathcal{X}'$ is a scheme,
\item $\mathcal{X}$ is DM if and only if $\mathcal{X}'$ is DM,
\item $\mathcal{X}$ is quasi-DM if and only if $\mathcal{X}'$ is quasi-DM,
\item $\mathcal{X}$ is separated if and only if $\mathcal{X}'$ is separated,
\item $\mathcal{X}$ is quasi-separated if and only if $\mathcal{X}'$ is
quasi-separated, and
\item add more here.
\end{enumerate}

There exist an open substack $\Curvesstack^{geomred} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{geomred}$,
\item the fibres of the morphism $X \to S$ are geometrically reduced
(More on Morphisms of Spaces, Definition
\ref{spaces-more-morphisms-definition-geometrically-reduced-fibre}),
\end{enumerate}
\item given a scheme $X$ proper over a field $k$ with $\dim(X) \leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{geomred}$,
\item $X$ is geometrically reduced over $k$.
\end{enumerate}
\end{enumerate}

There exist an open substack
$\Curvesstack^{+} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors through
$\Curvesstack^{+}$,
\item the singular locus of $X \to S$ endowed
with any/some closed subspace structure is finite over $S$.
\end{enumerate}
\item given $X$ a proper scheme over a field $k$ of dimension $\leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{+}$,
\item $X \to \Spec(k)$ is smooth except at finitely many points.
\end{enumerate}
\end{enumerate}

Let $S$ be a scheme.
Let $f : X \to Y$ be a representable morphism of algebraic spaces over $S$.
\begin{enumerate}
\item The morphism $f$ is locally separated.
\item The morphism $f$ is (quasi-)separated in the sense of
Definition \ref{definition-separated}
above if and only if $f$ is (quasi-)separated in the sense of
Section \ref{section-representable}.
\end{enumerate}
In particular, if $f : X \to Y$ is a morphism of schemes over $S$, then
$f$ is (quasi-)separated in the sense of
Definition \ref{definition-separated}
if and only if $f$ is (quasi-)separated as a morphism of schemes.

There exist an open substack $\Curvesstack^{CM} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{CM}$,
\item the morphism $X \to S$ is Cohen-Macaulay,
\end{enumerate}
\item given a scheme $X$ proper over a field $k$ with $\dim(X) \leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{CM}$,
\item $X$ is Cohen-Macaulay.
\end{enumerate}
\end{enumerate}

There exist an open substack $\Curvesstack^{lci} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors through
$\Curvesstack^{lci}$,
\item $X \to S$ is a local complete intersection morphism, and
\item $X \to S$ is a syntomic morphism.
\end{enumerate}
\item given $X$ a proper scheme over a field $k$ of dimension $\leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{lci}$,
\item $X$ is a local complete intersection over $k$.
\end{enumerate}
\end{enumerate}

There exist an open substack $\Curvesstack^{nodal} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $f : X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{nodal}$,
\item $f$ is at-worst-nodal of relative dimension $1$,
\end{enumerate}
\item given $X$ a scheme proper over a field $k$ with
$\dim(X) \leq 1$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{nodal}$,
\item the singularities of $X$ are at-worst-nodal and $X$
is equidimensional of dimension $1$.
\end{enumerate}
\end{enumerate}

Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
\begin{enumerate}
\item If $D \subset X$ is an effective Cartier divisor, then
the canonical section $1_D$ of $\mathcal{O}_X(D)$ is regular.
\item Conversely, if $s$ is a regular section of the invertible
sheaf $\mathcal{L}$, then there exists a unique effective
Cartier divisor $D = Z(s) \subset X$ and a unique isomorphism
$\mathcal{O}_X(D) \to \mathcal{L}$ which maps $1_D$ to $s$.
\end{enumerate}
The constructions
$D \mapsto (\mathcal{O}_X(D), 1_D)$ and $(\mathcal{L}, s) \mapsto Z(s)$
give mutually inverse maps
$$
\left\{
\begin{matrix}
\text{effective Cartier divisors on }X
\end{matrix}
\right\}
\leftrightarrow
\left\{
\begin{matrix}
\text{pairs }(\mathcal{L}, s)\text{ consisting of an invertible}\\
\mathcal{O}_X\text{-module and a regular global section}
\end{matrix}
\right\}
$$

\begin{reference}
\cite[Theorem 6.3 part 4)]{Jou}
\end{reference}
In Varieties, Situation \ref{varieties-situation-family-divisors} assume
\begin{enumerate}
\item $X$ is of finite type over $k$,
\item $X$ is geometrically irreducible over $k$,
\item there exist $v_1, v_2, v_3 \in V$ and an irreducible component
$Z$ of $H_{v_2} \cap H_{v_3}$ such that $Z \not \subset H_{v_1}$ and
$\text{codim}(Z, X) = 2$, and
\item every irreducible component $Y$ of $\bigcap_{v \in V} H_v$
has $\text{codim}(Y, X) \geq 2$.
\end{enumerate}
Then for general $v \in V \otimes_k k'$
the scheme $H_v$ is geometrically irreducible over $k'$.

Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
\begin{enumerate}
\item If $X$ is separated then $X$ is separated over $S$.
\item If $X$ is locally separated then $X$ is locally separated over $S$.
\item If $X$ is quasi-separated then $X$ is quasi-separated over $S$.
\end{enumerate}
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$.
\begin{enumerate}
\item[(4)] If $X$ is separated over $S$ then $f$ is separated.
\item[(5)] If $X$ is locally separated over $S$ then $f$ is locally separated.
\item[(6)] If $X$ is quasi-separated over $S$ then $f$ is quasi-separated.
\end{enumerate}

Strange flat modules.
\begin{enumerate}
\item There exists a ring $R$ and a finite flat $R$-module $M$ which is
not projective.
\item There exists a closed immersion which is flat but not open.
\end{enumerate}
